'use strict';
(function(){
  const portraits=new Map(),background=document.createElement('canvas'),snow=new Image();
  background.width=900;background.height=600;snow.src='assets/terrain/snow-v15.png';
  let mapReady=false,runtime=null,lastRoom='',selectedArena=0;
  const snowHeroes=['sentinel','arcanist','ranger','bulwark','shade','oracle'];
  function stop(){if(runtime){cancelAnimationFrame(runtime.raf);runtime=null;}}
  function avatar(id){if(portraits.has(id))return portraits.get(id);const target=document.createElement('canvas');target.width=96;target.height=116;try{if(typeof rift3d!=='undefined'&&rift3d&&!rendererFailed&&rift3d.portrait(id,target)){portraits.set(id,target);return target;}const source=document.querySelector('.model-portrait[data-model="'+id+'"]');if(source?.dataset.ready==='true'){target.getContext('2d').drawImage(source,0,0,96,116);portraits.set(id,target);return target;}}catch{}return null;}
  function members(d,arena){const list=(d.students||d.waitingMembers||[]).filter(p=>(p.arena||0)===arena),capacity=d.mode==='mass'?50:10;return Array.from({length:capacity},(_,slot)=>{const human=list.find(p=>p.roomSlot===slot),position=Object.keys(POSITIONS)[Math.floor(slot/2)%5];return human?{...human,bot:false}:{id:'preview-bot-'+slot,name:'บอต '+(slot+1),hero:d.activity==='snow'?snowHeroes[slot%snowHeroes.length]:botHero(position,d.ordinary?slot%2+Math.floor(slot/2):slot).id,team:slot%2,roomSlot:slot,bot:true};});}
  function mount(container,d,teacher=false){if(!container)return stop();if(runtime?.container===container&&runtime.d.code===d.code&&runtime.teacher===teacher){update(d);return;}stop();if(lastRoom!==d.code){lastRoom=d.code;selectedArena=d.student?.arena||0;}const arena=teacher?selectedArena:d.student.arena;
    container.innerHTML='<div class="waiting-map-top"><div><span class="lesson-eyebrow">'+(d.activity==='snow'?'SNOW SURVIVAL':'RIFT ARENA')+'</span><h2>แมพรอเข้าห้อง</h2></div>'+(teacher&&d.mode!=='mass'?'<label>ดูสนาม<select class="waiting-arena" aria-label="เลือกสนามบนแมพรอ">'+Array.from({length:5},(_,i)=>'<option value="'+i+'">สนาม '+(i+1)+'</option>').join('')+'</select></label>':'<span class="waiting-arena-label">สนาม '+(arena+1)+'</span>')+'</div><div class="waiting-map-summary" role="status"></div><div class="waiting-map-stage"><canvas aria-label="แมพรอแสดงฮีโร่ของผู้เล่นและตำแหน่งบอตที่จะเติมเมื่อเริ่มเกม"></canvas><div class="waiting-map-caption">'+(teacher?'เริ่มได้เมื่อมีนักเรียนอย่างน้อย 1 คน':d.ordinary?'เจ้าของห้องเริ่มได้เลย · ไม่ต้องรอครบ':'คุณเข้าห้องแล้ว · รอครูเริ่มเกม')+'</div></div><div class="waiting-legend"><span>ผู้เล่น</span><span>บอตที่จะเติมเมื่อเริ่ม</span><span>'+(teacher?'เลือกชื่อเพื่อเน้นตัวละคร':'วงสีเหลืองคือคุณ')+'</span></div><div class="waiting-members" aria-label="ผู้เล่นและบอตในสนาม"></div>';
    container.classList.toggle('waiting-dense',d.mode==='mass');const r=runtime={container,d,teacher,arena,surface:container.querySelector('canvas'),selected:d.student?.id,last:0};
    const select=container.querySelector('select');if(select){select.value=String(arena);select.onchange=()=>{r.arena=selectedArena=Number(select.value);update(r.d);};}update(d);r.raf=requestAnimationFrame(t=>draw(r,t));
  }
  function update(d){const r=runtime;if(!r||!r.container.isConnected)return stop();r.d=d;r.players=members(d,r.arena);const humans=r.players.filter(p=>!p.bot),bots=r.players.length-humans.length;r.container.querySelector('.waiting-map-summary').textContent=humans.length+' / '+r.players.length+' ผู้เล่นในสนาม · เติมบอต '+bots+' ตัว'+(humans.length?' · เริ่มได้เลย':' · รอนักเรียนเข้าห้อง');
    const key=r.players.map(p=>p.id+':'+p.hero+':'+p.name).join('|');if(key!==r.key){r.key=key;r.container.querySelector('.waiting-members').innerHTML=r.players.map(p=>'<button type="button" class="waiting-member '+(p.bot?'waiting-bot':'')+(p.id===r.selected?' selected':'')+'" data-waiting-id="'+escapeText(p.id)+'"><canvas width="72" height="84" aria-hidden="true" data-waiting-hero="'+escapeText(p.hero)+'"></canvas><b>'+escapeText(p.name)+'</b><span>'+escapeText(HEROES.find(h=>h.id===p.hero)?.name||p.hero)+'</span><small>'+(p.bot?'เติมเมื่อเริ่ม':p.id===d.student?.id?'คุณ':'ผู้เล่น')+'</small></button>').join('');for(const button of r.container.querySelectorAll('[data-waiting-id]'))button.onclick=()=>{r.selected=button.dataset.waitingId;for(const b of r.container.querySelectorAll('[data-waiting-id]'))b.classList.toggle('selected',b===button);};}
  }
  function draw(r,time){if(runtime!==r)return;if(!r.container.isConnected)return stop();r.raf=requestAnimationFrame(t=>draw(r,t));if(document.hidden||time-r.last<80)return;r.last=time;const rect=r.surface.getBoundingClientRect(),w=Math.round(rect.width),h=Math.round(rect.height);if(!w||!h)return;r.surface.width=w;r.surface.height=h;const c=r.surface.getContext('2d');
    if(r.d.activity==='snow'){c.fillStyle='#e1f4ff';c.fillRect(0,0,w,h);if(snow.complete&&snow.naturalWidth)c.drawImage(snow,0,0,w,h);}else{if(!mapReady){try{mapReady=!!(typeof rift3d!=='undefined'&&rift3d&&!rendererFailed&&rift3d.lobbyMap(background));}catch{}}c.fillStyle='#143d42';c.fillRect(0,0,w,h);if(mapReady)c.drawImage(background,0,0,w,h);else if(window.riftMapPreview)c.drawImage(window.riftMapPreview,0,0,w,h);}
    const dense=r.players.length===50,columns=dense&&w>=600?10:5,rows=r.players.length/columns,sx=w/(columns+1),sy=(h-58)/(rows+1),size=Math.max(24,Math.min(dense?48:70,sx*.78,sy*.72));
    for(const p of r.players){const i=p.roomSlot,x=sx*(i%columns+1),y=34+sy*(Math.floor(i/columns)+1),mine=p.id===r.d.student?.id,focus=p.id===r.selected,color=mine?'#ffe190':p.bot?'#c4dae0':p.team===0?'#6de3ed':'#ffa391';p.draw={x,y};c.save();c.globalAlpha=p.bot?.57:1;c.fillStyle='#071728b8';c.beginPath();c.ellipse(x,y+size*.38,size*.6,size*.23,0,0,Math.PI*2);c.fill();c.strokeStyle=focus?'#ffe190':color;c.lineWidth=focus?4:2;c.beginPath();c.ellipse(x,y+size*.35,size*.55,size*.18,0,0,Math.PI*2);c.stroke();const pic=avatar(p.hero);if(pic)c.drawImage(pic,x-size/2,y-size*.8+Math.sin(time/900+i)*1.4,size,size*1.21);else{c.fillStyle=color;c.font='bold '+Math.round(size*.55)+'px sans-serif';c.textAlign='center';c.fillText(HEROES.find(h=>h.id===p.hero)?.icon||'?',x,y);}c.globalAlpha=1;c.font='bold '+(dense?12:14)+'px "Noto Sans Thai",sans-serif';c.textAlign='center';const label=(mine?'คุณ · ':'')+p.name,limit=Math.max(4,Math.min(dense?9:16,Math.floor(sx/8))),shown=label.length>limit?label.slice(0,limit)+'…':label;c.lineWidth=4;c.strokeStyle='#071728';c.strokeText(shown,x,y+size*.65);c.fillStyle=color;c.fillText(shown,x,y+size*.65);c.restore();}
    for(const target of r.container.querySelectorAll('[data-waiting-hero]')){if(target.dataset.ready)continue;const pic=avatar(target.dataset.waitingHero);if(pic){target.getContext('2d').drawImage(pic,0,0,target.width,target.height);target.dataset.ready='true';}}
  }
  window.RiftWaitingMap={mount,update,stop};
})();
